-- Fake notes, replies and a support plan for the notes screens (TchNotes, Notes board).
-- Dev only (wtgxcptmucjerhufzjcf). Children are the de-identified dev replica's,
-- picked by enrolment order; note text is invented. Idempotent.

-- Notes written before tags existed get tags from their kind (domain tagsFromKind does the same at read time).
update vppsone.notes n set tags = case k.code when 'behaviour' then '{behaviour}' when 'praise' then '{talent}' when 'homework' then '{studies}' when 'health' then '{health}' when 'parent' then '{family}' else '{}' end::text[]
from vppsone.note_kinds k where k.id = n.kind_id and n.tags = '{}';

on conflict (id) do nothing;

on conflict (id) do nothing;

select 'a7e00000-0000-4000-8000-000000000031', '2026-27', n.student_id, n.class_id, n.id, 'Catch up in maths before the half-yearly exam', 'active', false, 'b9805a93-f3ee-4e53-a0df-e053b5fcb795', now() - interval '2 days', now() - interval '2 days', now() - interval '2 days'
from vppsone.notes n where n.id = 'a7e00000-0000-4000-8000-000000000016'
on conflict (id) do nothing;

on conflict (id) do nothing;
